{"content": "import yaml


def restore_workspace_from_yaml(state_yaml: str) -> dict:
    """Parse a YAML string representing workspace state and return it as a dictionary.

    Uses yaml.load with SafeLoader to safely deserialize the YAML string
    retrieved from client-side storage, preventing arbitrary code execution.
    """
    state = yaml.load(state_yaml, Loader=yaml.SafeLoader)
    if state is None:
        return {}
    if not isinstance(state, dict):
        raise ValueError("Expected YAML mapping at the top level, got: " + type(state).__name__)
    return state
